/**
 * North Carolina Broker Prelicensing — protected end-of-course examination.
 *
 * This module is intentionally outside every public/static content tree. The two provider-authored
 * forms are based only on the StateCourse curriculum and cited public authority; they are not copied
 * from, modelled on, or checked against North Carolina licence-examination questions.
 *
 * NCREC prescribes a comprehensive, closed-book, proctored examination, a 75% minimum grade and a
 * three-hour course allocation. NCREC does not prescribe the provider examination's item count in
 * the reviewed Syllabus or Rule 58H .0207. StateCourse therefore uses 48 scored items per form as a
 * review-draft school standard: three independently authored items for each of the sixteen sections.
 */

import MODULE_BANK from "../module-question-bank.mjs";

export const NORTH_CAROLINA_FINAL_EXAM_VERSION = "NC-FINAL-DRAFT-2026-09-07-v1";
export const NORTH_CAROLINA_FINAL_EXAM_ITEM_COUNT = 48;
export const NORTH_CAROLINA_FINAL_EXAM_TIME_LIMIT_MINUTES = 180;
export const NORTH_CAROLINA_FINAL_EXAM_PASSING_PERCENT = 75;

const MODULE_IDS = Object.freeze(Array.from({ length: 16 }, (_, index) => `module-${String(index + 1).padStart(2, "0")}`));

function q(form, number, moduleId, topic, prompt, correct, distractor1, distractor2, distractor3, rationale) {
  return Object.freeze({
    id: `NC-FINAL-${form}-${String(number).padStart(3, "0")}`,
    form,
    item: number,
    moduleId,
    section: MODULE_BANK[moduleId]?.syllabusSection,
    topic,
    prompt,
    choices: Object.freeze([correct, distractor1, distractor2, distractor3]),
    correctChoice: 0,
    rationale,
    curriculumReference: `north-carolina/curriculum/${moduleId}.md`,
  });
}

