export const NORTH_CAROLINA_PROTECTED_FINAL_FORMS = Object.freeze({ A: formA, B: formB });

const normalize = (value) => String(value ?? "").normalize("NFKC").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();

export function validateNorthCarolinaProtectedFinal(forms = NORTH_CAROLINA_PROTECTED_FINAL_FORMS) {
  const errors = [];
  const ids = new Set();
  const prompts = new Set();
  const trainingPrompts = new Set(Object.values(MODULE_BANK).flatMap((module) => [module.applied, ...module.engagement, ...module.remediation].map((item) => normalize(item.prompt))));

  for (const formName of ["A", "B"]) {
    const items = forms[formName];
    if (!Array.isArray(items) || items.length !== NORTH_CAROLINA_FINAL_EXAM_ITEM_COUNT) errors.push(`Form ${formName} must contain ${NORTH_CAROLINA_FINAL_EXAM_ITEM_COUNT} items.`);
    const moduleCounts = new Map(MODULE_IDS.map((moduleId) => [moduleId, 0]));
    for (const [index, item] of (items ?? []).entries()) {
      if (item.id !== `NC-FINAL-${formName}-${String(index + 1).padStart(3, "0")}`) errors.push(`${item.id}: id/order mismatch.`);
      if (ids.has(item.id)) errors.push(`${item.id}: duplicate id.`);
      ids.add(item.id);
      const normalizedPrompt = normalize(item.prompt);
      if (prompts.has(normalizedPrompt)) errors.push(`${item.id}: duplicate final prompt.`);
      if (trainingPrompts.has(normalizedPrompt)) errors.push(`${item.id}: reuses a formative prompt.`);
      prompts.add(normalizedPrompt);
      if (!MODULE_IDS.includes(item.moduleId) || item.section !== MODULE_BANK[item.moduleId]?.syllabusSection) errors.push(`${item.id}: invalid module/section mapping.`);
      moduleCounts.set(item.moduleId, (moduleCounts.get(item.moduleId) ?? 0) + 1);
      if (!Array.isArray(item.choices) || item.choices.length !== 4 || new Set(item.choices.map(normalize)).size !== 4 || item.correctChoice !== 0) errors.push(`${item.id}: invalid authored choices/key.`);
      if (normalizedPrompt.split(" ").length < 8 || !item.prompt.endsWith("?")) errors.push(`${item.id}: deficient prompt.`);
      if (normalize(item.rationale).split(" ").length < 10) errors.push(`${item.id}: deficient rationale.`);
      if (item.curriculumReference !== `north-carolina/curriculum/${item.moduleId}.md`) errors.push(`${item.id}: missing curriculum reference.`);
    }
    for (const [moduleId, count] of moduleCounts) if (count !== 3) errors.push(`Form ${formName}: ${moduleId} has ${count} items; expected 3.`);
  }
  if (errors.length) throw new Error(`North Carolina protected-final guard failed:\n${errors.join("\n")}`);
  return Object.freeze({ forms: 2, itemsPerForm: 48, totalItems: 96, sectionsPerForm: 16, itemsPerSection: 3, passingPercent: 75, timeLimitMinutes: 180 });
}

function rng(seed) {
  let value = 2166136261;
  for (const character of seed) value = Math.imul(value ^ character.charCodeAt(0), 16777619) >>> 0;
  return () => {
    value = (Math.imul(value, 1664525) + 1013904223) >>> 0;
    return value / 4294967296;
  };
}

function shuffle(values, random) {
  const result = [...values];
  for (let index = result.length - 1; index > 0; index -= 1) {
    const swap = Math.floor(random() * (index + 1));
    [result[index], result[swap]] = [result[swap], result[index]];
  }
  return result;
}

/**
 * Creates a reproducible attempt without exposing the key. The caller must persist attemptSeed,
 * form, version, timestamps, proctor authorization and the exact answer map in protected storage.
 * This utility does not claim that a production proctoring workflow has been validated.
 */
export function prepareNorthCarolinaFinalExam({ form, attemptSeed } = {}) {
  if (!Object.hasOwn(NORTH_CAROLINA_PROTECTED_FINAL_FORMS, form) || typeof attemptSeed !== "string" || attemptSeed.length < 16) {
    throw new Error("A valid form and a persisted attempt seed of at least 16 characters are required.");
  }
  const source = NORTH_CAROLINA_PROTECTED_FINAL_FORMS[form];
  const choiceRandom = rng(`${NORTH_CAROLINA_FINAL_EXAM_VERSION}:${form}:${attemptSeed}:choices`);
  const targetPositions = shuffle(source.map((_, index) => index % 4), choiceRandom);
  const keyed = source.map((item, index) => {
    const distractorIndexes = shuffle([1, 2, 3], choiceRandom);
    const authoredIndexes = [...distractorIndexes];
    authoredIndexes.splice(targetPositions[index], 0, 0);
    return {
      id: item.id,
      section: item.section,
      prompt: item.prompt,
      choices: Object.freeze(authoredIndexes.map((choiceIndex) => item.choices[choiceIndex])),
      correctChoice: targetPositions[index],
    };
  });
  const ordered = shuffle(keyed, rng(`${NORTH_CAROLINA_FINAL_EXAM_VERSION}:${form}:${attemptSeed}:items`));
  const questions = Object.freeze(ordered.map(({ id, section, prompt, choices }) => Object.freeze({ id, section, prompt, choices })));

  return Object.freeze({
    version: NORTH_CAROLINA_FINAL_EXAM_VERSION,
    form,
    itemCount: NORTH_CAROLINA_FINAL_EXAM_ITEM_COUNT,
    timeLimitMinutes: NORTH_CAROLINA_FINAL_EXAM_TIME_LIMIT_MINUTES,
    passingPercent: NORTH_CAROLINA_FINAL_EXAM_PASSING_PERCENT,
    closedBook: true,
    proctored: true,
    questions,
    grade(answers) {
      if (!answers || typeof answers !== "object" || Array.isArray(answers) || Object.keys(answers).length !== keyed.length) {
        throw new Error("Every final-exam item must have one recorded answer.");
      }
      for (const item of keyed) {
        if (!Number.isInteger(answers[item.id]) || answers[item.id] < 0 || answers[item.id] > 3) throw new Error(`Invalid answer for ${item.id}.`);
      }
      const missed = keyed.filter((item) => answers[item.id] !== item.correctChoice).map((item) => item.id);
      const correct = keyed.length - missed.length;
      const percent = Math.round((correct / keyed.length) * 100);
      return Object.freeze({ correct, total: keyed.length, percent, passed: percent >= NORTH_CAROLINA_FINAL_EXAM_PASSING_PERCENT, missed: Object.freeze(missed) });
    },
  });
}

validateNorthCarolinaProtectedFinal();
